BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Projected misstatement vs. performance materiality evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Technologies, the engagement team sets overall materiality at $200,000 and performance materiality at $150,000. A projected misstatement of $120,000 is identified from inventory sampling. Under AU-C 450, the auditor should:', '["Compare the projected misstatement to performance materiality and evaluate whether further procedures are needed to reduce audit risk", "Immediately issue a qualified opinion because the projected misstatement exceeds 50% of overall materiality", "Request management to adjust the financial statements by exactly $120,000 before performing any additional procedures", "Disregard the projected misstatement because it falls below overall materiality of $200,000"]'::jsonb, 0, 'Under AU-C 450.06, the auditor evaluates whether uncorrected misstatements are material individually or in aggregate. When a projected misstatement approaches performance materiality, the auditor considers whether additional procedures are needed to reduce the risk that total uncorrected misstatements exceed overall materiality. Simply comparing to overall materiality (choice D) ignores the purpose of performance materiality as a buffer against aggregate risk.', 'medium', 3),

-- Q2: hard / L4 — Fraud vs. error distinction when evaluating misstatement intent
(1, 'Misstatements and Control Deficiencies', 'Pinnacle Financial Group''s auditor discovers a $45,000 revenue misstatement where management recorded a December 2025 sale that did not ship until January 2026. The controller claims it was an honest mistake, but the auditor notes the entity nearly missed a debt covenant ratio. Under AU-C 240 and AU-C 450, the auditor should:', '["Accept management''s explanation and treat the misstatement as an error since the controller acknowledged the mistake", "Evaluate whether the misstatement may be indicative of fraud, considering the debt covenant pressure as a risk factor, and reassess the nature and extent of audit procedures", "Automatically report the misstatement to law enforcement as suspected fraud since the entity had financial pressure", "Reduce overall materiality by 50% and reperform all substantive tests for every account balance"]'::jsonb, 1, 'Under AU-C 240.35, when a misstatement is identified, the auditor evaluates whether it may be indicative of fraud. AU-C 450.A17 notes that circumstances surrounding misstatements, including incentives such as debt covenant pressure, affect evaluation. The auditor must exercise professional skepticism rather than simply accepting management''s explanation (choice A), while automatically reporting to law enforcement (choice C) exceeds the auditor''s obligation at this stage.', 'hard', 4),

-- Q3: medium / L2 — Clearly trivial threshold application
(1, 'Misstatements and Control Deficiencies', 'At Greenfield Associates, the audit team establishes overall materiality at $500,000 and designates amounts below $10,000 as clearly trivial. During testing, the team identifies a $7,500 misstatement in prepaid expenses. Under AU-C 450, the auditor should:', '["Accumulate the misstatement on the summary of uncorrected misstatements and communicate it to management", "Report the $7,500 misstatement directly to those charged with governance as a potential material weakness", "Not accumulate the misstatement because it falls below the clearly trivial threshold and would not be expected to be material even if aggregated", "Reduce the clearly trivial threshold to $5,000 to capture additional small misstatements"]'::jsonb, 2, 'Under AU-C 450.05, the auditor need not accumulate misstatements that are clearly trivial. Clearly trivial is not the same as "not material" — it means amounts so small they would not be material even when aggregated with other misstatements. Since $7,500 falls below the $10,000 clearly trivial threshold, accumulation is not required. Accumulating it (choice A) confuses the clearly trivial threshold with the posting threshold for documentation.', 'medium', 2),

-- Q4: easy / L1 — Accumulation requirement for identified misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, the auditor is required to accumulate misstatements identified during the audit unless they are:', '["Below overall materiality for the financial statements", "Immaterial when considered individually", "Not related to a material account balance", "Clearly trivial"]'::jsonb, 3, 'AU-C 450.05 states the auditor shall accumulate misstatements identified during the audit, other than those that are clearly trivial. Clearly trivial refers to amounts well below any reasonable materiality threshold, not merely amounts below overall materiality (choice A). Being immaterial individually (choice B) does not exempt a misstatement from accumulation since aggregate effects must still be considered.', 'easy', 1),

-- Q5: easy / L1 — Definition of a control deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a control deficiency exists when:', '["A control is designed, implemented, or operated in a way that does not allow timely prevention or detection of misstatements", "Management identifies and corrects a misstatement before the financial statements are issued", "The auditor discovers a misstatement that exceeds overall materiality", "An employee makes an isolated clerical error that is caught by a supervisor''s review"]'::jsonb, 0, 'AU-C 265.07 defines a control deficiency as existing when the design or operation of a control does not allow management or employees to prevent or detect misstatements on a timely basis. A deficiency may be in design or in operation. An error caught by supervisory review (choice D) actually indicates the control is working as intended, not that a deficiency exists.', 'easy', 1),

-- Q6: medium / L2 — Prior-year uncorrected misstatements carried forward
(1, 'Misstatements and Control Deficiencies', 'While planning the current-year audit of Bayshore Manufacturing, the engagement team reviews the prior-year summary of uncorrected misstatements totaling $85,000. Overall materiality for the current year is $400,000. Under AU-C 450, the auditor should:', '["Disregard prior-year uncorrected misstatements because a new audit period begins with a clean slate", "Require management to record adjusting entries for all prior-year uncorrected misstatements before starting fieldwork", "Consider the effect of prior-year uncorrected misstatements on the current-year financial statements when evaluating current-year results", "Automatically reduce current-year materiality by $85,000 to account for the carried-forward effect"]'::jsonb, 2, 'AU-C 450.A7 requires the auditor to consider the effect of uncorrected misstatements from prior periods on current-period financial statements. Prior-year misstatements may have continuing effects through opening balances. Disregarding them entirely (choice A) ignores carryover impact, while automatically reducing materiality by the prior-year amount (choice D) is not a requirement of the standard.', 'medium', 2),

-- Q7: hard / L4 — Rollover vs. iron curtain approach for quantifying misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade Utilities, the engagement partner evaluates $180,000 in uncorrected misstatements accumulated over three years against current-year materiality of $250,000. The current-year originating misstatement is only $35,000, but the cumulative balance sheet effect is $180,000. Under SAB 108 guidance on quantifying misstatements, the auditor should:', '["Use only the rollover approach, considering the $35,000 current-year origination, and conclude the misstatement is immaterial", "Use only the iron curtain approach, considering the $180,000 balance sheet effect, and require full correction", "Ignore both approaches because they apply only to SEC registrants and are irrelevant under AU-C standards", "Consider both the rollover and iron curtain approaches to evaluate the misstatement''s effect on the income statement and balance sheet"]'::jsonb, 3, 'SAB 108 (Topic 1N) requires a dual approach — evaluating misstatements using both the rollover method (income statement focus, current-year origination) and the iron curtain method (balance sheet focus, cumulative effect). Under AU-C 450.A13, auditors similarly consider both individual and aggregate effects. Using only one approach (choices A or B) risks overlooking material misstatements from the other perspective.', 'hard', 4),

-- Q8: medium / L3 — Pervasiveness of misstatements affecting opinion type
(1, 'Misstatements and Control Deficiencies', 'Silverstone Retail''s auditor identifies $300,000 in uncorrected misstatements that management refuses to correct. Overall materiality is $250,000. The misstatements affect revenue, inventory, and accounts receivable across all operating segments. Under AU-C 705, the auditor should evaluate whether the uncorrected misstatements are:', '["Material but not pervasive, resulting in a qualified opinion", "Material and pervasive, warranting consideration of an adverse opinion", "Immaterial because the misstatements are spread across multiple accounts rather than concentrated in one", "Outside the scope of the audit, requiring a disclaimer of opinion"]'::jsonb, 1, 'Under AU-C 705.08, when misstatements are both material (exceeding $250,000 materiality) and pervasive (affecting multiple elements across the financial statements), an adverse opinion is appropriate. Pervasiveness is assessed by whether effects are confined to specific elements or widespread. Misstatements spanning revenue, inventory, and receivables across all segments indicate pervasive effects. A qualified opinion (choice A) applies only when material but not pervasive.', 'medium', 3),

-- Q9: easy / L1 — Timing deadline for written MW communication
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, the auditor''s written communication of material weaknesses to those charged with governance must be made no later than:', '["5 business days after identifying the material weakness", "The date the audit report is issued", "60 days following the report release date", "30 days before the entity''s annual shareholder meeting"]'::jsonb, 2, 'AU-C 265.13 requires written communication of significant deficiencies and material weaknesses to those charged with governance no later than 60 days following the report release date. This deadline provides time for the auditor to fully evaluate deficiency severity. Requiring communication by the report issuance date (choice B) does not reflect the actual standard''s 60-day deadline.', 'easy', 1),

-- Q10: hard / L3 — Tainting factor in ratio-based sample projection
(1, 'Misstatements and Control Deficiencies', 'During the audit of Horizon Logistics, the auditor selects a sample of 60 shipping invoices from a population of 3,000 items totaling $1.8 million. Three sample items contain pricing errors: a $5,000 item with a $500 overstatement, an $8,000 item with a $1,200 overstatement, and a $3,000 item with a $900 overstatement. To project the misstatement using the ratio method, the auditor should:', '["Calculate the error rate as a proportion of sampled dollar value and apply it to the total population value to estimate projected misstatement", "Multiply the total sample error of $2,600 by the ratio of population count to sample count", "Use only the largest individual error of $1,200 as the projected misstatement for the entire population", "Sum the three errors to report $2,600 as the total projected misstatement without extrapolation"]'::jsonb, 0, 'Under AU-C 530.A20, the ratio projection method uses the relationship between misstatements found and sampled item values to project to the population. The auditor calculates the total error relative to total sampled value and applies that rate to the population. Simply multiplying the raw error by a count ratio (choice B) ignores the varying sizes of sampled items. Reporting only the sample error (choice D) fails to project to the population.', 'hard', 3),

-- Q11: easy / L1 — Communication of lesser deficiencies to management
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, control deficiencies that are not significant deficiencies or material weaknesses but merit attention should be communicated to:', '["Those charged with governance in writing within 60 days", "Management, either in writing or orally", "External regulatory agencies responsible for oversight", "The entity''s external legal counsel for legal evaluation"]'::jsonb, 1, 'AU-C 265.12 requires the auditor to communicate to management control deficiencies identified during the audit that are of sufficient importance to merit management''s attention, even if they do not rise to significant deficiency level. This communication may be oral or written. Communication to governance in writing (choice A) is required only for significant deficiencies and material weaknesses.', 'easy', 1),

-- Q12: medium / L2 — IT general control deficiency severity evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Northbridge Data Systems, the auditor discovers that multiple employees share a single login to the accounting software, eliminating individual accountability. No unique user IDs are required. Under AU-C 265, the most important factor when evaluating the severity of this IT control deficiency is:', '["Whether the shared login violates the entity''s written IT security policy document", "The cost of implementing individual user accounts relative to the IT budget", "Whether any employee has formally complained about the shared login arrangement", "Whether the lack of individual accountability could prevent timely detection of unauthorized transactions"]'::jsonb, 3, 'Under AU-C 265.A7, deficiency severity depends on the magnitude of potential misstatement and the likelihood that the deficiency could result in one. Shared logins eliminate individual accountability, impairing the entity''s ability to detect unauthorized or erroneous transactions. Whether a written policy exists (choice A) is less relevant than whether the control gap creates actual risk of undetected misstatements in the financial statements.', 'medium', 2),

-- Q13: medium / L2 — SUM schedule communication and management correction request
(1, 'Misstatements and Control Deficiencies', 'After completing fieldwork at Lakewood Industries, the auditor prepares a summary of uncorrected misstatements totaling $75,000 against overall materiality of $300,000. Under AU-C 450, this summary should:', '["Include only factual misstatements, excluding judgmental and projected misstatements", "Be communicated only to those charged with governance and withheld from management", "Be communicated to management with a request to correct the misstatements, describing the nature and effect of each item", "Be filed internally by the auditor without communication since the total is below materiality"]'::jsonb, 2, 'AU-C 450.08 requires the auditor to communicate all accumulated uncorrected misstatements to management and request correction. The communication describes individual misstatements and their aggregate effect. All categories — factual, judgmental, and projected — must be included, not just factual (choice A). Filing without communication (choice D) violates the standard even when the aggregate is below materiality.', 'medium', 2),

-- Q14: medium / L2 — Testing remediation of prior-year material weakness
(1, 'Misstatements and Control Deficiencies', 'During the prior-year audit of Crestwood Financial, the auditor reported a material weakness in the bank reconciliation process. In the current year, management states it has remediated the weakness by hiring a new accountant and adding supervisory review. Under AU-C 265, the auditor should:', '["Accept management''s representation that the weakness has been remediated without additional testing", "Test the redesigned controls to determine whether the material weakness has been effectively remediated before removing it from the current-year communication", "Automatically include the same material weakness in the current-year communication because it was reported in the prior year", "Communicate the weakness as a significant deficiency instead, since management has taken some corrective steps"]'::jsonb, 1, 'Under AU-C 265.A14, the auditor should test controls to determine whether previously reported deficiencies have been remediated. Management''s assertion alone is insufficient — the auditor must obtain evidence that new controls are properly designed and operating effectively. Automatically repeating the finding (choice C) ignores successful remediation, while accepting management''s word alone (choice A) lacks sufficient audit evidence.', 'medium', 2),

-- Q15: hard / L4 — Prudent official test applied to high-volume deficiency
(1, 'Misstatements and Control Deficiencies', 'Atlas Healthcare''s auditor identifies a control deficiency in patient billing. The actual misstatement detected is only $12,000 against materiality of $500,000, but the deficiency affects a process handling $50 million annually with no compensating controls. Applying the prudent official test, the auditor concludes the deficiency is a material weakness because:', '["The $12,000 actual misstatement demonstrates complete control failure regardless of transaction volume", "The deficiency has existed for more than one fiscal year without management detection", "Patient billing is inherently high-risk due to the complexity of healthcare regulations alone", "A reasonable possibility exists that a material misstatement could occur and not be prevented or detected given the volume of transactions exposed to the deficiency"]'::jsonb, 3, 'Under AU-C 265.A12, a material weakness exists when there is a reasonable possibility that a material misstatement would not be prevented or detected. The prudent official concept evaluates what a knowledgeable person would conclude about severity. Although the actual error is small, the $50 million exposure with no compensating controls creates reasonable possibility of material misstatement. Focusing solely on the actual error amount (choice A) conflates actual with potential impact.', 'hard', 4),

-- Q16: medium / L3 — Qualitative materiality of disclosure omissions
(1, 'Misstatements and Control Deficiencies', 'During the audit of Evergreen Capital, the auditor discovers that a required disclosure about a $40,000 related-party transaction was omitted. Overall materiality is $1 million, and the transaction is quantitatively immaterial. Under AU-C 450, the auditor should evaluate the misstatement by:', '["Considering the qualitative nature of the omission, since a related-party disclosure failure may be material regardless of the dollar amount involved", "Concluding the omission is immaterial because $40,000 is well below the $1 million materiality threshold", "Adding the $40,000 to the summary of uncorrected misstatements and performing no further qualitative evaluation", "Requiring management to restate prior-year financial statements to include the related-party disclosure"]'::jsonb, 0, 'AU-C 450.A16 emphasizes that qualitative factors — including the nature of misstatements and surrounding circumstances — must be considered in evaluating materiality. Related-party disclosure omissions carry heightened qualitative significance under AU-C 550 because they affect users'' understanding of key relationships. Relying solely on quantitative thresholds (choice B) fails to consider the qualitative materiality dimension of the omission.', 'medium', 3),

-- Q17: medium / L3 — Recurring misstatements indicating systemic deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westfield Manufacturing, the auditor notes that the same type of inventory valuation misstatement has recurred for three consecutive years with amounts of $30,000, $25,000, and $35,000. Each amount was individually immaterial against $400,000 materiality. Under AU-C 450, the auditor should:', '["Ignore the pattern because each year''s misstatement was individually corrected before financial statement issuance", "Conclude the misstatements are immaterial since the largest is only 8.75% of materiality", "Evaluate whether the recurring nature indicates a systemic control deficiency that could lead to a material misstatement", "Require management to change its inventory valuation method to eliminate future misstatements"]'::jsonb, 2, 'Under AU-C 450.A6, the auditor considers whether uncorrected misstatements indicate a pattern or systematic issue. Recurring misstatements of the same nature across multiple periods suggest an underlying control deficiency meriting evaluation under AU-C 265. The auditor assesses whether the deficiency could produce a material misstatement in future periods. Focusing only on individual-year amounts (choice B) overlooks the trend and systemic risk.', 'medium', 3),

-- Q18: medium / L3 — Management bias indicators in accounting estimates
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Realty Group, the auditor observes that management''s property impairment estimates have consistently been at the optimistic end of the reasonable range for four consecutive years, resulting in higher reported asset values. Under AU-C 450 and AU-C 540, the auditor should:', '["Accept each individual estimate since it falls within the auditor''s established reasonable range", "Require management to use the midpoint of each reasonable range for all future estimates", "Disclose the pattern in the audit report as an emphasis-of-matter paragraph", "Evaluate whether the pattern of consistently optimistic estimates indicates possible management bias and consider the cumulative effect on the financial statements"]'::jsonb, 3, 'Under AU-C 540.A131 and AU-C 450.A17, the auditor evaluates indicators of possible management bias in estimates. A consistent pattern of estimates falling at one end of the reasonable range may indicate intentional bias, even if each individual estimate is within bounds. The auditor must assess the cumulative effect and consider fraud risk implications. Accepting each estimate in isolation (choice A) fails to address the concerning pattern.', 'medium', 3),

-- Q19: medium / L3 — Compensating control effect on deficiency severity classification
(1, 'Misstatements and Control Deficiencies', 'At Summit Construction, the auditor finds that the accounts payable clerk can both create vendors and process payments without supervisory approval — a segregation-of-duties deficiency. However, the controller performs detailed monthly reviews of all new vendor additions and payment activity. Under AU-C 265, the auditor should:', '["Classify the deficiency as a material weakness regardless because segregation-of-duties failures are always material weaknesses", "Evaluate whether the controller''s compensating review adequately reduces the risk of material misstatement before determining the deficiency''s severity classification", "Conclude no deficiency exists because the controller''s review eliminates the segregation-of-duties concern entirely", "Report the deficiency as a significant deficiency without evaluating the effectiveness of compensating controls"]'::jsonb, 1, 'Under AU-C 265.A8, the auditor considers the existence and effectiveness of compensating controls when evaluating deficiency severity. A compensating control does not eliminate the deficiency (choice C) but may reduce risk sufficiently to affect classification. The auditor must evaluate whether the controller''s review is effectively designed and operating to mitigate the segregation risk. Blanket classification as a material weakness (choice A) ignores compensating control considerations.', 'medium', 3),

-- Q20: easy / L2 — Communication of deficiency below significant deficiency level
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinecrest Landscaping, the auditor identifies a control deficiency in petty cash that does not rise to significant deficiency level but warrants management''s attention. Under AU-C 265, the auditor should:', '["Include the deficiency in the written communication to governance alongside any significant deficiencies", "Document the deficiency in the audit file but withhold it from management", "Communicate the deficiency to management either in writing or orally", "Issue a separate formal report to the audit committee identifying the deficiency"]'::jsonb, 2, 'AU-C 265.12 requires the auditor to communicate to management control deficiencies that merit attention but are not significant deficiencies or material weaknesses. This communication may be either written or oral, unlike the governance communication which must be in writing. The auditor is not required to withhold such findings (choice B) — the standard encourages timely communication to the appropriate level.', 'easy', 2),

-- Q21: medium / L2 — Dual-purpose testing revealing both deficiency and misstatement
(1, 'Misstatements and Control Deficiencies', 'While performing dual-purpose testing at Bridgeport Electronics, the auditor tests 40 purchase orders for both control effectiveness and substantive accuracy. Three items show proper approval signatures but incorrect pricing that the reviewer failed to catch. The pricing errors total $18,000 against materiality of $750,000. Under AU-C 265 and AU-C 450, the auditor should:', '["Evaluate only the $18,000 substantive misstatement and ignore control implications since approvals were present", "Project the $18,000 to the population and immediately issue a qualified opinion", "Treat the findings solely as a control deficiency since the pricing errors were below materiality", "Evaluate the pricing review failure as a control deficiency and accumulate the $18,000 as a misstatement for aggregate evaluation"]'::jsonb, 3, 'Under AU-C 265.A5, dual-purpose tests may reveal both control deficiencies and misstatements. The reviewer''s failure to catch pricing errors indicates a deficiency in the review control''s operation. Separately under AU-C 450, the pricing errors must be accumulated as misstatements. The auditor should not evaluate only one dimension (choices A or C) — both control and substantive implications require assessment.', 'medium', 2),

-- Q22: hard / L4 — PCAOB integrated audit vs. AU-C framework differences
(1, 'Misstatements and Control Deficiencies', 'An auditor transitioning from a private company audit under AICPA standards to an SEC registrant audit under PCAOB standards classified a revenue recognition control deficiency as a significant deficiency under AU-C 265 in the prior year. Under PCAOB AS 2201 for the integrated audit, the auditor should recognize that:', '["PCAOB standards require an opinion on internal control over financial reporting, which may result in the same deficiency being classified as a material weakness under the more stringent reporting framework", "AU-C 265 and PCAOB AS 2201 use identical definitions and severity thresholds, so the classification remains unchanged", "PCAOB standards do not require evaluation of internal control deficiencies for public company audits", "The auditor must apply AU-C 265 standards to all engagements regardless of whether the entity is public or private"]'::jsonb, 0, 'Under PCAOB AS 2201.62-70, auditors of SEC registrants must issue an opinion on internal control effectiveness, applying evaluation criteria that may classify deficiencies differently than AU-C 265. The integrated audit''s requirement to opine on controls creates heightened scrutiny, and deficiencies classified as significant under AU-C 265 may be elevated to material weaknesses under PCAOB standards. The two frameworks are not identical (choice B) in application and reporting.', 'hard', 4),

-- Q23: hard / L4 — Restatement implications for prior-period MW assessment
(1, 'Misstatements and Control Deficiencies', 'After Granite Holdings restates its prior-year financial statements to correct a $2.3 million inventory error, the current-year auditor must assess internal control implications. The prior-year auditor had not identified any material weaknesses. Under AU-C 265, the current-year auditor should:', '["Rely on the prior-year auditor''s assessment that no material weaknesses existed since they were responsible for that period", "Conclude the restatement automatically means the current year also has a material weakness in inventory", "Limit the assessment to current-year controls only since the restatement relates to a prior period", "Evaluate whether the restatement''s cause indicates a material weakness that existed in the prior period and whether similar control deficiencies persist currently"]'::jsonb, 3, 'Under AU-C 265.A3, the auditor considers conditions that call into question prior conclusions. A restatement indicates a material misstatement was not prevented or detected — a strong indicator of a prior-period material weakness. The current auditor must evaluate whether the underlying control deficiency persists. Relying on the prior auditor''s assessment (choice A) is inappropriate when the restatement demonstrates that assessment was incorrect.', 'hard', 4),

-- Q24: medium / L3 — Monitoring component deficiency under COSO framework
(1, 'Misstatements and Control Deficiencies', 'During the audit of Riverside Health Systems, the auditor discovers that management has not performed any internal control monitoring activities for 18 months due to staff turnover. No separate evaluations or ongoing monitoring occurred. Under AU-C 265 and the COSO framework, the auditor should evaluate this finding as:', '["A minor operational issue unrelated to internal control over financial reporting", "A potential material weakness because the absence of monitoring means deficiencies in other control components may have gone undetected", "A significant deficiency reducible to a lesser classification if management promises to resume monitoring", "An acceptable situation during staff turnover since controls may still operate effectively without monitoring"]'::jsonb, 1, 'Under the COSO framework, monitoring ensures other controls continue functioning. AU-C 265.A10 recognizes that a monitoring component deficiency can be particularly severe because it allows other deficiencies to exist undetected. An 18-month gap with no monitoring creates reasonable possibility that material misstatements went undetected. Management''s promise to resume monitoring (choice C) does not retroactively address the gap period.', 'medium', 3),

-- Q25: easy / L1 — Deficiency in design definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a deficiency in design exists when:', '["An employee fails to perform a properly designed control procedure", "Management has not documented the entity''s internal control policies", "A necessary control is missing or not properly designed to meet a control objective", "The auditor cannot obtain sufficient evidence about a control''s effectiveness"]'::jsonb, 2, 'AU-C 265.A5 distinguishes between design and operation deficiencies. A design deficiency exists when a control necessary to meet a control objective is missing or not properly designed to prevent or detect misstatements. When an employee fails to perform a properly designed control (choice A), that represents a deficiency in operation rather than design — the control exists but does not function as intended.', 'easy', 1),

-- Q26: easy / L1 — Deficiency in operation definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, a deficiency in operation exists when:', '["The entity lacks a formal internal control framework document", "A control objective cannot be achieved by any combination of controls", "Management has not established adequate monitoring activities", "A properly designed control does not operate effectively or is not performed by a person with appropriate authority or competence"]'::jsonb, 3, 'AU-C 265.A5 defines an operation deficiency as occurring when a properly designed control does not operate effectively, or when the person performing the control lacks necessary authority, competence, or objectivity. This differs from a design deficiency where the control itself is missing or improperly designed. Lack of a framework document (choice A) relates to design considerations rather than operational effectiveness.', 'easy', 1),

-- Q27: easy / L1 — Written communication must include restricted-use statement
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, the auditor''s written communication of significant deficiencies and material weaknesses must include:', '["A statement that the communication is intended solely for those charged with governance, management, and others within the organization", "A guarantee that no other control deficiencies exist beyond those identified", "A detailed description of every control the auditor tested during the engagement", "An opinion on the overall effectiveness of the entity''s internal control system"]'::jsonb, 0, 'AU-C 265.13 requires the written communication to include a restricted-use statement limiting distribution to management, those charged with governance, and others within the organization. The auditor cannot guarantee all deficiencies were identified (choice B), as the audit was not designed to identify all deficiencies. The communication does not constitute an opinion on internal control effectiveness (choice D).', 'easy', 1),

-- Q28: medium / L2 — Safeguarding controls and asset misappropriation risk
(1, 'Misstatements and Control Deficiencies', 'During the audit of Coastal Warehousing, the auditor discovers that warehouse access is unrestricted and no periodic physical inventory counts are performed. No inventory shortage has been detected this year. Under AU-C 265, the absence of safeguarding controls over inventory should be evaluated based on:', '["Whether management carries adequate insurance to cover potential theft losses", "The reasonable possibility that assets could be lost or misappropriated, potentially resulting in a material misstatement to the financial statements", "Whether employees have historically been trustworthy based on their employment records", "The replacement cost of the inventory compared to the entity''s total revenue"]'::jsonb, 1, 'Under AU-C 265.A9, the auditor evaluates whether deficiencies in safeguarding controls could result in material misstatement of the financial statements. The focus is on reasonable possibility of loss leading to financial statement impact, not insurance coverage (choice A) or employee trustworthiness (choice C). The absence of basic physical controls creates vulnerability regardless of whether losses have yet occurred.', 'medium', 2),

-- Q29: easy / L1 — Three categories of misstatements under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, the three categories of misstatements are:', '["Factual misstatements, judgmental misstatements, and projected misstatements", "Material misstatements, immaterial misstatements, and clearly trivial misstatements", "Intentional misstatements, unintentional misstatements, and systematic misstatements", "Quantitative misstatements, qualitative misstatements, and disclosure misstatements"]'::jsonb, 0, 'AU-C 450.A3-A5 identifies three categories: factual misstatements (errors about which there is no doubt), judgmental misstatements (differences in estimates the auditor considers unreasonable), and projected misstatements (the auditor''s best estimate of population misstatements based on sample results). The alternative categorizations (choices B, C, D) are not the framework established by AU-C 450.', 'easy', 1),

-- Q30: medium / L2 — Subsequent events affecting misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'While evaluating uncorrected misstatements at Apex Manufacturing near the end of fieldwork, the auditor learns that a major customer representing 15% of accounts receivable has filed for bankruptcy. The receivable was not previously on the summary of uncorrected misstatements. Under AU-C 450 and AU-C 560, the auditor should:', '["Ignore the subsequent event because uncorrected misstatements are evaluated only as of the balance sheet date without regard to later events", "Consider whether the subsequent event provides additional evidence about conditions existing at the balance sheet date and reassess the collectibility of the receivable", "Automatically add the full receivable balance to the summary of uncorrected misstatements as a factual misstatement", "Issue the audit report immediately before the subsequent event can affect the financial statements"]'::jsonb, 1, 'Under AU-C 560.09-10, the auditor evaluates whether subsequent events provide evidence of conditions that existed at the balance sheet date. If the customer''s financial difficulties existed before year-end, the bankruptcy filing provides evidence that the receivable may have been impaired at that date. This is not automatically a factual misstatement (choice C) but rather additional evidence for reassessing the existing balance. Ignoring subsequent events (choice A) violates AU-C 560.', 'medium', 2)
;

COMMIT;
